SOURCE='"""Receipt-bound dependency CAS and PG-only rollback. No action on import.\n\nProduction execution is possible only through the reviewed host operator. Public\nconfiguration is pinned; this module never accepts a DB URI, password, RPC URL,\nnew image, or arbitrary SQL from a client.\n"""\nimport copy\nimport hashlib\nimport json\nimport re\nimport subprocess\nimport os\nimport selectors\nimport time\nfrom pathlib import Path\n\nOLD_IMAGE=\'sha256:a53c65ac2aee00217f206f07f4ddecbf9d55b5a43f60bf87858d9756259ba730\'\nOLD_ID=\'b6ff8c7a6f5c2282e29883de917f2d376a8e92efffecc45d115338e0516a5201\'\nCATALOG_SHA=\'2d54c8a4ab1e3360fdf702af0113c27739dcddf44abd4e0682f68606005652d7\'\nCATALOG_PATH=\'/data/studio/keel-inline-fragment-catalog-\'+CATALOG_SHA+\'.json\'\nOLD_CATALOG_SHA=\'16e9a686827d500eb2a85803e48820244abdd12ef1e35f21ee7dd1c7988df191\'\nCONFIG_SHA=\'9543c71f9f506e5243c9a74a3d70007ab6919c9f4eb76c0fec8ad7cdb40a77eb\'\nHOST_SHA=\'9ebb974a9d71321d58a0bb74a528d089a6a4337a54328460a9768ff260e56467\'\nMOUNTS_SHA=\'8227ad2f93c93f7a55ba2006d6b73695ae8b04f636a637bc54b08dc65298996f\'\nBASELINE_SHA=\'1fc4a3c27c2afde33e24a69930195d792810748305ab4f1a2e5291287ad62deb\'\nENABLE_SHA=\'2b62d8ee1b33228acb4ac19a1b95fae9ba2826496b72586d60a09ba4187fcf0e\'\nDISABLE_SHA=\'bf7b04e48d09027c57a15e203ab967f89735f1568eb3b2c65f27635ef1660c8b\'\nSUPERVISOR_SHA=\'d357df6c3f75f62592a6f7c815583c521f8f34b274bcdbe358dcddb8fe0d5b9e\'\nSOCKET=\'/run/keel-rollback-postgres\'\nPG=\'/usr/lib/postgresql/17/bin/\'\nPG_ARGS=[\'-D\',\'/data/postgres\',\'-c\',\'listen_addresses=\',\'-c\',\'port=5432\',\'-c\',\'unix_socket_directories=\'+SOCKET,\'-c\',\'shared_buffers=32MB\',\'-c\',\'max_connections=4\',\'-c\',\'work_mem=2MB\',\'-c\',\'maintenance_work_mem=16MB\',\'-c\',\'log_statement=none\']\nCATALOG_ENV=\'KEEL_INLINE_FRAGMENT_CATALOG_PATH\'\n\ndef require(ok, reason):\n    if not ok: raise RuntimeError(reason)\n\ndef digest(value):\n    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(\',\',\':\')).encode()).hexdigest()\n\ndef sha(value): return hashlib.sha256(value).hexdigest()\n\ndef validate_spec(plan):\n    d=plan[\'dependencies\']\n    require(d[\'schema\']==\'keel.receipt-bound-publication-dependencies@1\',\'dependency_schema\')\n    require(d[\'catalogSHA256\']==CATALOG_SHA and d[\'catalogPath\']==CATALOG_PATH,\'catalog_identity\')\n    require(d[\'enableSQLSHA256\']==ENABLE_SHA and d[\'disableSQLSHA256\']==DISABLE_SHA,\'factory_sql_identity\')\n    for k in (\'helperSHA256\',\'bootstrapBaseSHA256\',\'bootstrapSHA256\',\'runtimeSupervisorSHA256\'):\n        require(re.fullmatch(\'[0-9a-f]{64}\',d[k]) is not None,\'dependency_digest\')\n    require(d[\'runtimeSupervisorSHA256\']==SUPERVISOR_SHA,\'startup_fence_source_changed\')\n    name=d[\'pgOnlyName\']\n    require(re.fullmatch(\'keel-[a-z0-9][a-z0-9_.-]{1,100}\',name) is not None,\'pg_helper_name\')\n    require(name not in {plan[k] for k in (\'candidateName\',\'runnerName\',\'rollbackName\',\'failedName\',\'socketVolume\')} and name!=\'keel-showcase-paid-release-capacity-20261008\',\'pg_helper_name_collision\')\n    return d\n\ndef read_files(root, plan):\n    d=validate_spec(plan)\n    names={\'catalog.proposed.json\':CATALOG_SHA,\'factory-baseline.sql\':BASELINE_SHA,\'factory-enable.sql\':ENABLE_SHA,\'factory-disable.sql\':DISABLE_SHA,\'receipt-bound-dependencies.py\':d[\'helperSHA256\']}\n    values={}\n    for name,expected in names.items():\n        p=Path(root)/name\n        require(not p.is_symlink() and p.is_file() and p.stat().st_size<=65536,\'dependency_file_invalid\')\n        values[name]=p.read_bytes();require(sha(values[name])==expected,\'dependency_file_changed\')\n    return values\n\ndef assert_old(old, strict=True):\n    require(old[\'Id\']==OLD_ID and old[\'Image\']==OLD_IMAGE,\'old_runtime_identity\')\n    if strict:\n        require(digest(old[\'Config\'])==CONFIG_SHA and digest(old[\'HostConfig\'])==HOST_SHA and digest(old[\'Mounts\'])==MOUNTS_SHA,\'old_configuration_changed\')\n    data=[m for m in old[\'Mounts\'] if m[\'Destination\']==\'/data\']\n    require(len(data)==1 and all(data[0].get(k)==v for k,v in {\'Type\':\'volume\',\'Name\':\'keel-showcase-ovh\',\'Source\':\'/var/lib/docker/volumes/keel-showcase-ovh/_data\',\'Destination\':\'/data\',\'RW\':True}.items()),\'old_data_mount_changed\')\n    return data[0]\n\ndef public_database_names(old):\n    pairs={}\n    for value in old[\'Config\'][\'Env\']:\n        require(isinstance(value,str) and \'=\' in value,\'old_environment_invalid\')\n        k,v=value.split(\'=\',1);require(k not in pairs,\'old_environment_duplicate\');pairs[k]=v\n    names=[pairs.get(\'POSTGRES_USER\',\'keel\'),pairs.get(\'POSTGRES_DB\',\'keel_studio\')]\n    require(all(re.fullmatch(\'[A-Za-z_][A-Za-z0-9_]{0,62}\',v) is not None for v in names),\'database_identifier_invalid\')\n    return names\n\ndef labels(plan):\n    return {\'io.keel.studio.rollout.id\':plan[\'activationId\'],\'io.keel.studio.rollout.role\':\'rollback-postgres-only\'}\n\n# Only public daemon defaults are copied, never original runtime environment or\n# namespace/device/capability settings. The complete old HostConfig is pinned by\n# assert_old before these fields are used.\nORDINARY_DAEMON_FIELDS=(\'LogConfig\',\'ShmSize\',\'ConsoleSize\',\'MaskedPaths\',\'ReadonlyPaths\',\'Runtime\',\'Isolation\')\n\ndef ordinary_daemon_defaults(old):\n    host=old[\'HostConfig\']\n    require(all(k in host for k in ORDINARY_DAEMON_FIELDS),\'old_daemon_defaults_missing\')\n    require(host[\'Runtime\']==\'runc\' and host[\'Isolation\'] in (\'\',\'default\'),\'old_daemon_runtime_unreviewed\')\n    require(type(host[\'ShmSize\']) is int and 0<=host[\'ShmSize\']<=64*1024**2,\'old_daemon_shm_unreviewed\')\n    console=host[\'ConsoleSize\']\n    require(isinstance(console,list) and len(console)==2 and all(type(v)is int and 0<=v<=65535 for v in console),\'old_daemon_console_unreviewed\')\n    log=host[\'LogConfig\']\n    require(isinstance(log,dict) and set(log)=={\'Type\',\'Config\'} and log[\'Type\'] in (\'json-file\',\'local\',\'none\') and isinstance(log[\'Config\'],dict),\'old_daemon_logging_unreviewed\')\n    require(set(log[\'Config\'])<={\'max-size\',\'max-file\',\'compress\'} and all(isinstance(v,str) for v in log[\'Config\'].values()),\'old_daemon_log_options_unreviewed\')\n    for field in (\'MaskedPaths\',\'ReadonlyPaths\'):\n        require(isinstance(host[field],list) and all(isinstance(v,str) and v.startswith(\'/\') and \'..\'not in v.split(\'/\') for v in host[field]),\'old_daemon_sandbox_paths_unreviewed\')\n    return {k:copy.deepcopy(host[k]) for k in ORDINARY_DAEMON_FIELDS}\n\ndef neutral_daemon_value(value):\n    # New Docker versions may add inert fields. Empty known sandbox paths are\n    # NOT handled here: they are present in expected and compared exactly.\n    return value is None or value is False or (type(value)in(int,float) and value==0) or (type(value)is str and value==\'\') or (type(value)in(list,dict) and len(value)==0)\n\ndef pg_only_configuration(old,plan,image):\n    assert_old(old)\n    public_database_names(old)\n    require(image[\'Id\']==OLD_IMAGE and image[\'Os\']==\'linux\' and image[\'Architecture\']==\'amd64\',\'old_pg_image_identity\')\n    require(set(image[\'Config\'].get(\'Volumes\')or{})=={\'/var/lib/postgresql/data\'},\'old_image_volume_declarations\')\n    defaults=image[\'Config\'].get(\'Env\')or[]\n    keys=[v.split(\'=\',1)[0] for v in defaults]\n    require(len(keys)==len(set(keys)) and all(re.fullmatch(\'[A-Za-z_][A-Za-z0-9_]*\',v) for v in keys),\'old_image_environment_keys\')\n    ordinary=ordinary_daemon_defaults(old)\n    # Docker preserves image healthcheck timings when Test is disabled. Bind\n    # those exact pinned-image defaults while preventing probe execution.\n    healthcheck={**copy.deepcopy(image[\'Config\'].get(\'Healthcheck\')or{}),\'Test\':[\'NONE\']}\n    return {\'Image\':OLD_IMAGE,\'User\':\'999:999\',\'Env\':[k+\'=\' for k in sorted(keys)],\'Entrypoint\':[\'/usr/bin/env\',\'-i\',PG+\'postgres\'],\'Cmd\':PG_ARGS,\'Labels\':labels(plan),\'WorkingDir\':\'/\',\'StopSignal\':\'SIGINT\',\'ExposedPorts\':copy.deepcopy(image[\'Config\'].get(\'ExposedPorts\')or{}),\'Volumes\':{},\'Healthcheck\':healthcheck,\'HostConfig\':{**ordinary,\'NetworkMode\':\'none\',\'ReadonlyRootfs\':True,\'Privileged\':False,\'Memory\':268435456,\'MemorySwap\':268435456,\'NanoCpus\':1000000000,\'PidsLimit\':32,\'CapDrop\':[\'ALL\'],\'SecurityOpt\':[\'no-new-privileges\'],\'IpcMode\':\'private\',\'CgroupnsMode\':\'private\',\'Init\':False,\'RestartPolicy\':{\'Name\':\'no\',\'MaximumRetryCount\':0},\'PortBindings\':{},\'PublishAllPorts\':False,\'Binds\':[\'keel-showcase-ovh:/data:rw\'],\'Mounts\':[],\'Tmpfs\':{SOCKET:\'rw,noexec,nosuid,nodev,size=1m,uid=999,gid=999,mode=0700\',\'/var/lib/postgresql/data\':\'rw,noexec,nosuid,nodev,size=1m,uid=999,gid=999,mode=0700\'}}}\n\ndef assert_pg_only(value,old,plan,image):\n    expected=pg_only_configuration(old,plan,image)\n    require(value[\'Image\']==OLD_IMAGE and all((value[\'Config\'].get(\'Labels\')or{}).get(k)==v for k,v in labels(plan).items()),\'pg_helper_not_owned\')\n    require(sorted(value[\'Config\'].get(\'Env\')or[])==sorted(expected[\'Env\']),\'pg_helper_config_Env\')\n    for k in (\'User\',\'Entrypoint\',\'Cmd\',\'WorkingDir\',\'StopSignal\',\'Healthcheck\'):\n        require(value[\'Config\'].get(k)==expected[k],\'pg_helper_config_\'+k)\n    require((value[\'Config\'].get(\'ExposedPorts\')or{})==expected[\'ExposedPorts\'],\'pg_helper_exposed_ports\')\n    for k,v in expected[\'HostConfig\'].items():\n        actual=value[\'HostConfig\'].get(k)\n        if k in (\'PortBindings\',\'Mounts\'):require(not actual,\'pg_helper_host_\'+k)\n        else:require(actual==v,\'pg_helper_host_\'+k)\n    for key,actual in value[\'HostConfig\'].items():\n        if key not in expected[\'HostConfig\']:\n            require(neutral_daemon_value(actual),\'pg_helper_unreviewed_host_\'+key)\n    require(not any((value.get(\'NetworkSettings\',{}).get(\'Ports\')or{}).values()),\'pg_helper_published_ports\')\n    mounts=value[\'Mounts\'];require(all(m[\'Type\']in(\'volume\',\'tmpfs\')for m in mounts),\'pg_helper_extra_mount\')\n    volume=[m for m in mounts if m[\'Type\']==\'volume\']\n    require(len(volume)==1 and all(volume[0].get(k)==v for k,v in {\'Name\':\'keel-showcase-ovh\',\'Destination\':\'/data\',\'Source\':\'/var/lib/docker/volumes/keel-showcase-ovh/_data\',\'RW\':True}.items()),\'pg_helper_volume\')\n    require({m[\'Destination\'] for m in mounts if m[\'Type\']==\'tmpfs\'}<={SOCKET,\'/var/lib/postgresql/data\'} and len(mounts)==len({m[\'Destination\']for m in mounts}),\'pg_helper_scratch\')\n\n# Fixed inner execFileSync has an independent deadline/output cap. Only approved\n# SQL bytes and public user/database identifiers cross this boundary, no secrets.\nPSQL_SUPERVISOR=r\'\'\'const cp=require(\'child_process\'),h=require(\'crypto\');const [id,user,db,socket,encoded]=process.argv.slice(1);let sql=Buffer.from(encoded,\'base64\');let r={schema:\'keel.factory-cas-exec@1\',sqlSHA256:h.createHash(\'sha256\').update(sql).digest(\'hex\'),result:\'FAIL\'};try{const out=cp.execFileSync(\'/usr/lib/postgresql/17/bin/psql\',[\'--no-psqlrc\',\'--host\',socket,\'--port\',\'5432\',\'--username\',user,\'--dbname\',db,\'--set\',\'ON_ERROR_STOP=1\',\'--no-align\',\'--tuples-only\'],{input:sql,timeout:15000,killSignal:\'SIGKILL\',maxBuffer:16384,env:{PATH:\'\',PGCONNECT_TIMEOUT:\'3\',PGOPTIONS:\'-c statement_timeout=10000 -c lock_timeout=5000\'}});r.result=\'PASS\';r.outputSHA256=h.createHash(\'sha256\').update(out).digest(\'hex\');r.outputBytes=out.length}catch(e){r.category=e.code===\'ETIMEDOUT\'?\'deadline\':e.code===\'ENOBUFS\'?\'output-limit\':\'sql-or-process-error\';r.exitStatus=e.status}process.stdout.write(JSON.stringify(r));process.exitCode=r.result===\'PASS\'?0:1;\'\'\'\n\ndef run_control(argv,timeout):\n    """Bound host diagnostics independently of the in-container supervisor."""\n    process=subprocess.Popen(argv,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL)\n    output=bytearray();deadline=time.monotonic()+timeout\n    try:\n        with selectors.DefaultSelector() as selector:\n            selector.register(process.stdout,selectors.EVENT_READ)\n            while selector.get_map():\n                require(time.monotonic()<deadline,\'control_deadline\')\n                for key,_ in selector.select(min(.1,max(0,deadline-time.monotonic()))):\n                    chunk=os.read(key.fileobj.fileno(),4096)\n                    if not chunk:selector.unregister(key.fileobj);continue\n                    require(len(output)+len(chunk)<=4096,\'control_output_limit\')\n                    output.extend(chunk)\n        code=process.wait(timeout=max(.001,deadline-time.monotonic()))\n        return code,bytes(output)\n    finally:\n        if process.poll() is None:process.kill();process.wait(timeout=5)\n        process.stdout.close()\n\ndef execute_fixed_sql(identity,old,sql,expected_sha,socket=\'/data/postgres-socket\'):\n    import base64\n    require(re.fullmatch(\'[0-9a-f]{64}\',identity) is not None,\'cas_container_identity\')\n    require(expected_sha in (DISABLE_SHA,BASELINE_SHA) and sha(sql)==expected_sha,\'only_exact_reviewed_sql_allowed\')\n    user,db=public_database_names(old)\n    argv=[\'docker\',\'exec\',\'--user\',\'999:999\',identity,\'/usr/local/bin/node\',\'-e\',PSQL_SUPERVISOR,identity,user,db,socket,base64.b64encode(sql).decode()]\n    code,output=run_control(argv,20)\n    require(len(output)<=2048,\'cas_control_output_limit\')\n    value=json.loads(output)\n    require(code==0 and value.get(\'schema\')==\'keel.factory-cas-exec@1\' and value.get(\'result\')==\'PASS\' and value.get(\'sqlSHA256\')==expected_sha,\'factory_disable_not_confirmed\')\n    return value\n\ndef execute_sql(identity,old,sql,socket=\'/data/postgres-socket\'):\n    return execute_fixed_sql(identity,old,sql,DISABLE_SHA,socket)\n\ndef assert_database_baseline(old,sql):\n    assert_old(old)\n    return execute_fixed_sql(old[\'Id\'],old,sql,BASELINE_SHA)\n\nINSTALL_CATALOG=r\'\'\'const f=require(\'fs\'),h=require(\'crypto\');const p=process.argv[1],buf=Buffer.from(process.argv[2],\'base64\'),expected=process.argv[3];if(h.createHash(\'sha256\').update(buf).digest(\'hex\')!==expected)throw Error(\'input-hash\');for(const q of [\'/data\',\'/data/studio\']){let s=f.lstatSync(q);if(!s.isDirectory()||s.isSymbolicLink())throw Error(\'parent\')}if(f.existsSync(p)){const s=f.lstatSync(p);if(!s.isFile()||s.isSymbolicLink()||(s.mode&511)!==292||h.createHash(\'sha256\').update(f.readFileSync(p)).digest(\'hex\')!==expected)throw Error(\'existing-catalog-mismatch\')}else{const fd=f.openSync(p,f.constants.O_WRONLY|f.constants.O_CREAT|f.constants.O_EXCL|f.constants.O_NOFOLLOW,256);try{f.writeFileSync(fd,buf);f.fsyncSync(fd);f.fchmodSync(fd,292);f.fsyncSync(fd)}finally{f.closeSync(fd)}const dir=f.openSync(\'/data/studio\',f.constants.O_RDONLY|f.constants.O_DIRECTORY|f.constants.O_NOFOLLOW);try{f.fsyncSync(dir)}finally{f.closeSync(dir)}}if(h.createHash(\'sha256\').update(f.readFileSync(p)).digest(\'hex\')!==expected)throw Error(\'readback\');process.stdout.write(JSON.stringify({schema:\'keel.catalog-install@1\',sha256:expected,bytes:buf.length,path:p}));\'\'\'\n\ndef install_catalog(identity,catalog):\n    import base64\n    require(identity==OLD_ID and sha(catalog)==CATALOG_SHA,\'catalog_install_identity\')\n    code,output=run_control([\'docker\',\'exec\',\'--user\',\'999:999\',identity,\'/usr/local/bin/node\',\'-e\',INSTALL_CATALOG,CATALOG_PATH,base64.b64encode(catalog).decode(),CATALOG_SHA],15)\n    require(code==0 and len(output)<=2048,\'catalog_install_failed\')\n    value=json.loads(output);require(value=={\'schema\':\'keel.catalog-install@1\',\'sha256\':CATALOG_SHA,\'bytes\':len(catalog),\'path\':CATALOG_PATH},\'catalog_install_result\');return value\n\ndef rollback_database(docker,old,applications,plan,sql,persist,execute=execute_sql,sleep=time.sleep):\n    """Disable before any old app restart; uncertain helper create is reconciled.\n\n    persist is the parent\'s durable receipt writer. Any exception leaves old\n    stopped and records the last phase. No helper or volume is ever removed.\n    """\n    require(len(applications)<=1,\'multiple_candidate_database_owners\')\n    status={\'schema\':\'keel.factory-rollback@1\',\'confirmed\':False,\'helperId\':None,\'helperRetained\':True,\'databaseRestorePerformed\':False}\n    def record(phase):status[\'phase\']=phase;persist(copy.deepcopy(status))\n    assert_old(docker.container(old[\'Id\']))\n    record(\'disabling-before-candidate-stop\')\n    if docker.container(old[\'Id\'])[\'State\'][\'Running\']:\n        require(all(docker.container(i)[\'State\'][\'Running\'] is False for i in applications),\'old_and_candidate_running\')\n        status[\'cas\']=execute(old[\'Id\'],old,sql)\n        status[\'confirmed\']=True;record(\'baseline-or-disabled-through-unchanged-original\');return status\n    for identity in applications:\n        value=docker.container(identity)\n        if value[\'State\'][\'Running\']:\n            try:\n                status[\'cas\']=execute(identity,old,sql)\n                status[\'confirmed\']=True\n                record(\'disabled-through-candidate\')\n                return status\n            except BaseException:\n                # PG may be dead while supervisor is running. Never start old\n                # until the exact stopped-data helper confirms the same CAS.\n                record(\'candidate-cas-unconfirmed\')\n    # No write has occurred if startup never reached DB. Still use CAS to prove\n    # baseline/no-own-row instead of guessing from an HTTP health outcome.\n    for identity in applications:\n        docker.action(identity,\'stop\',\'?t=30\')\n        require(docker.container(identity)[\'State\'][\'Running\'] is False,\'candidate_not_stopped_for_pg\')\n    require(docker.container(old[\'Id\'])[\'State\'][\'Running\'] is False,\'old_not_stopped_for_pg\')\n    require(all(docker.container(i)[\'State\'][\'Running\'] is False for i in applications),\'candidate_restarted_for_pg\')\n    record(\'pg-only-create-attempt\')\n    image=docker.image(OLD_IMAGE)\n    helper=docker.maybe_container(plan[\'dependencies\'][\'pgOnlyName\'])\n    if helper is None:\n        try:helper_id=docker.create(plan[\'dependencies\'][\'pgOnlyName\'],pg_only_configuration(old,plan,image))\n        except BaseException:\n            helper=docker.maybe_container(plan[\'dependencies\'][\'pgOnlyName\'])\n            require(helper is not None,\'pg_helper_create_uncertain_not_found\')\n            helper_id=helper[\'Id\']\n        helper=docker.container(helper_id)\n    assert_pg_only(helper,old,plan,image)\n    require(helper[\'State\'][\'Running\'] is False,\'pg_helper_already_running\')\n    helper_id=helper[\'Id\'];status[\'helperId\']=helper_id;record(\'pg-only-guarded-before-start\')\n    try:\n        require(docker.container(old[\'Id\'])[\'State\'][\'Running\'] is False and all(docker.container(i)[\'State\'][\'Running\'] is False for i in applications),\'database_owner_restarted_before_pg\')\n        docker.action(helper_id,\'start\')\n        assert_pg_only(docker.container(helper_id),old,plan,image)\n        record(\'pg-only-started\')\n        # Readiness is local-only and bounded. No initdb, no host auth changes.\n        for attempt in range(30):\n            require(docker.container(helper_id)[\'State\'][\'Running\'],\'pg_only_exited\')\n            ready=subprocess.run([\'docker\',\'exec\',\'--user\',\'999:999\',helper_id,PG+\'pg_isready\',\'--host\',SOCKET,\'--port\',\'5432\',\'--timeout\',\'1\'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=3,check=False)\n            if ready.returncode==0:break\n            sleep(.25)\n        else:raise RuntimeError(\'pg_only_ready_deadline\')\n        status[\'cas\']=execute(helper_id,old,sql,SOCKET)\n        record(\'pg-only-cas-confirmed\')\n    finally:\n        record(\'pg-only-clean-stop-attempt\')\n        try:docker.action(helper_id,\'stop\',\'?t=30\')\n        except BaseException:\n            require(docker.container(helper_id)[\'State\'][\'Running\'] is False,\'pg_only_stop_uncertain\')\n        stopped=docker.container(helper_id);assert_pg_only(stopped,old,plan,image)\n        require(stopped[\'State\'][\'Running\'] is False and stopped[\'State\'].get(\'ExitCode\')==0 and stopped[\'State\'].get(\'OOMKilled\') is False,\'pg_only_clean_stop_not_confirmed\')\n        record(\'pg-only-clean-stop-confirmed\')\n    require(\'cas\' in status,\'factory_disable_not_confirmed\')\n    status[\'confirmed\']=True;record(\'factory-disabled-safe-for-old-runtime\');return status\n'
