class Connection(http.client.HTTPConnection):
 def connect(self):
  self.sock=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);self.sock.settimeout(20);self.sock.connect('/var/run/docker.sock')
def request(method,path,body=None,missing=False):
 c=Connection('localhost',timeout=20)
 try:
  data=json.dumps(body).encode()if body is not None else None
  c.request(method,'/v1.47'+path,body=data,headers={'Content-Type':'application/json'}if data else{})
  response=c.getresponse();raw=response.read(1048577);need(len(raw)<=1048576,'docker_output_limit')
  if missing and response.status==404:return None
  need(200<=response.status<300,'docker_http_'+str(response.status));return json.loads(raw)if raw else None
 finally:c.close()
